import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.Path;

class LocalFolderExtractor {

    private File makeFile(final Path file) throws IOException {
        if(file.getParent() == null) return null;
        Files.createDirectories(file.getParent());
        return file.toFile();
    }

package org.yamcs.yarch.streamsql;
import org.yamcs.yarch.ColumnDefinition;
import org.yamcs.yarch.CompiledExpression;
import org.yamcs.yarch.ConstantValueCompiledExpression;
import org.yamcs.yarch.DataType;
import java.util.List;
import java.util.UUID;
import org.yamcs.time.Instant;
import org.yamcs.utils.parser.ParseException;

public class ValueExpression extends Expression {

    private void escapeJavaString(String str, StringBuilder sb) {
        int sz;
        sz = str.length();
        for (int i = 0; i < sz; i++) {
            char ch = str.charAt(i);

            // handle unicode
            if (ch > 0xfff) {
                sb.append("\\u" + Integer.toHexString(ch).toUpperCase());
            } else if (ch > 0xff) {
                sb.append("\\u0" + Integer.toHexString(ch).toUpperCase());
            } else if (ch > 0x7f) {
                sb.append("\\u00" + Integer.toHexString(ch).toUpperCase());
            } else if (ch < 32) {
                switch (ch) {
                case '\b':
                    sb.append('\\');
                    sb.append('b');
                    break;
                case '\n':
                    sb.append('\\');
                    sb.append('n');
                    break;
                case '\t':
                    sb.append('\\');
                    sb.append('t');
                    break;
                case '\f':
                    sb.append('\\');
                    sb.append('f');
                    break;
                case '\r':
                    sb.append('\\');
                    sb.append('r');
                    break;
                default:
                    if (ch > 0xf) {
                        sb.append("\\u00" + Integer.toHexString(ch).toUpperCase());
                    } else {
                        sb.append("\\u000" + Integer.toHexString(ch).toUpperCase());
                    }
                    break;
                }
            } else {
                switch (ch) {
                case '"':
                    sb.append('\\');
                    sb.append('"');
                    break;
                case '\\':
                    sb.append('\\');
                    sb.append('\\');
                    break;
                default:
                    sb.append(ch);
                    break;
                }
            }
        }
    }

