            w.newLine();
            w.write("  DISPLAY=:123.456");
            w.newLine();
            w.write("  export DISPLAY");
            w.newLine();
            w.write("fi");
            w.newLine();
            w.write("ssh -i \"" + key.toAbsolutePath() + "\" -l \"" + user + "\" "
                    + getHostKeyFactory().forCliGit(listener).getVerifyHostKeyOption(knownHosts) + " \"$@\"");
