        copy.setAttribute("scope", codeCache.getScope());

        codeCache.setAuthentication(copy);


        return redis
                .opsForValue()
                .set(getRedisKey(code), codeCache, Duration.ofMinutes(5))
                .thenReturn(new AuthorizationCodeResponse(code));
