                Files.copy(zis, file, StandardCopyOption.REPLACE_EXISTING);
            }
        }
        try {
            // Validate local files against central directory for CVE-2007-4546 and CVE-2014-2720
            vis.validate(set);
        } catch (IOException e) {
            Utils.deleteQuietly(dest);
            throw e;
        }
    }

