            FilePath[] r = new FilePath(f).list(reportFilePath);

            XMLInputFactory factory = XMLInputFactory.newInstance();
            factory.setProperty("javax.xml.stream.supportDTD", false);

            for (FilePath filePath : r) {
                InputStream is = null;
                XMLEventReader reader = null;
