                    throw new IOException(filePath + " is not an XML file, please check your report pattern");
                } finally {
                    try {
                        if (reader != null) {
                            try {
                                reader.close();
                            } catch (XMLStreamException ex) {
                                //
                            }
                        }
                    } finally {
                        IOUtils.closeQuietly(is);
                    }
                }

            }
            return r;
        }

