import com.cavisson.jenkins.PageDetail;

public class NetStormConnectionManager extends BaseConnection{

				public void run()
				{
					try {

						/*Keeping flag based on TestRun status on server.*/
						boolean isTestRunning = true;

						/*Initial Sleep Before Polling.*/
						try {

							/*Delay to poll due to test is taking time to start.*/
							Sleep(pollInterval * 1000);    

						} catch (Exception ex) {
							logger.log(Level.SEVERE, "Cavisson-Plugin|Error in initial sleep before polling.", ex);
						}

						logger.log(Level.FINE, "Cavisson-Plugin|Starting Polling to server.");

						/*Running Thread till test stopped.*/
						while (isTestRunning) {
							try {

								logger.log(Level.FINE, "Cavisson-Plugin|Testrun number = "+ testRun);
								/*Creating Polling URL.*/
								String pollURLWithArgs = pollURL + "?proSubProject=" + scenarioName + "&testRun=" + testRun;    	

								URL url = new URL(pollURLWithArgs);
								URLConnection conn = getConnections(url, isSkipSSLCertValidation(), isSkipSSLHostValidation());
								conn.setConnectTimeout(POLL_CONN_TIMEOUT);
								conn.setReadTimeout(POLL_CONN_TIMEOUT);
								((HttpURLConnection) conn).setRequestMethod("GET");
								conn.setRequestProperty("Accept", "application/json");    

								if (((HttpURLConnection) conn).getResponseCode() != 200) {
									logger.log(Level.INFO, "Cavisson-Plugin|Getting Error code on polling  = " + ((HttpURLConnection) conn).getResponseCode() + ". Retrying in next poll in 5 minutes.");
								}

								BufferedReader br = new BufferedReader(new InputStreamReader(conn.getInputStream()));
								String pollResString = br.readLine();

								try {
									JSONObject pollResponse = (JSONObject) JSONSerializer.toJSON(pollResString);

									/*Getting TestRun, if not available.*/
									if (testRun <= 0) {
										testRun = pollResponse.getInt("testRun");
										int stopTR = -1;
										stopTR = pollResponse.getInt("testRun");
										String portStr = getUrlString();
										new BuildActionStopTest(stopTR,username,portStr);
									}

									if(pollResponse.getBoolean("status")) {
										/*Terminating Loop when test is stopped.*/
										isTestRunning = false;
									}

									testCycleNum = pollResponse.getString("testCycleNumber");  

									if(doNotWaitforTestCompletion == true) {
										if(testRun > 0) {
											isTestRunning = false;
										}
									}
								} catch (Exception e) {
									logger.log(Level.SEVERE, "Cavisson-Plugin|Error in parsing polling response = " + pollResString, e);
								}

								/*Closing Stream.*/
								try {
									br.close();
								} catch (Exception e) {
									logger.log(Level.SEVERE, "Cavisson-Plugin|Error in closing stream inside polling thread.", e);
								}
							} catch (Exception e) {
								logger.log(Level.SEVERE, "Cavisson-Plugin|Error in polling running testRun with interval. Retrying after 5 sec.", e);
							}

							/*Repeating till Test Ended.*/
							try {
								consoleLogger.println("Test in progress. Going to check on server. Time = " + new Date() + ", pollInterval = " + pollInterval);

								if(testRun > 0)
									pollInterval  = 60;

								if(isTestRunning == true)
									Sleep(pollInterval * 1000);

							} catch (Exception ex) {       	
								logger.log(Level.SEVERE, "Cavisson-Plugin|Error in polling connection in loop", ex);
							} 
						}

					} catch (Exception e) {
						logger.log(Level.SEVERE, "Cavisson-Plugin|Error in polling running testRun with interval.", e);
					}
				}

